'AC14.1.22'; from __future__ import annotations; from pathlib import Path; import pytest; from common.testing import generate_epic_status as ges
def test_AC14_1_22_splice_requires_markers() -> None:
    'AC14.1.22'
    with pytest.raises(ValueError): ges.splice_block('no markers here', 'BLOCK')
    document = f'before\n{ges.BEGIN_MARKER}\nold\n{ges.END_MARKER}\nafter\n'; new_block = f'{ges.BEGIN_MARKER}\nnew\n{ges.END_MARKER}'; spliced = ges.splice_block(document, new_block); assert 'old' not in spliced; assert 'new' in spliced; assert spliced.startswith('before\n'); assert spliced.endswith('after\n'); 'AC14.1.22'; 'AC14.1.22'; _m1_repo_root = Path(__file__).resolve().parents[2]; _m1_readme = _m1_repo_root / 'README.md'; _m1_document = _m1_readme.read_text(encoding='utf-8'); assert ges.BEGIN_MARKER in _m1_document, 'README is missing the generated EPIC block'; _m1_pointer = ges.render_pointer_block(); assert ges.splice_block(_m1_document, _m1_pointer) == _m1_document; assert 'tools/build_ac_traceability.py' in _m1_pointer; assert '| EPIC-001 |' not in _m1_pointer
def test_AC14_1_22_check_passes_when_block_current(tmp_path: Path) -> None: 'AC14.1.22'; pointer = ges.render_pointer_block(); doc = tmp_path / 'README.md'; doc.write_text(f'intro\n{pointer}\noutro\n', encoding='utf-8'); assert ges.main(['--output', str(doc), '--check']) == 0
def test_AC14_1_22_check_fails_on_drift(tmp_path: Path, capsys) -> None: 'AC-meta.generated-refs.3'; doc = tmp_path / 'README.md'; doc.write_text(f'intro\n{ges.BEGIN_MARKER}\nSTALE numbers\n{ges.END_MARKER}\noutro\n', encoding='utf-8'); assert ges.main(['--output', str(doc), '--check']) == 1; assert 'pointer block' in capsys.readouterr().err.lower()
def test_AC14_1_22_check_fails_when_markers_missing(tmp_path: Path, capsys) -> None: 'AC14.1.22'; doc = tmp_path / 'README.md'; doc.write_text('no markers\n', encoding='utf-8'); assert ges.main(['--output', str(doc), '--check']) == 1; assert 'markers' in capsys.readouterr().err.lower()
